    /**
     * Get the Transit Phal (gochar results) narrative — the slow grahas (Mars, Jupiter, Saturn,
     * Rahu, Ketu) by sign, their transit counted from the natal Moon and from the natal lagna, Sade
     * Sati while it runs, the Sun's transit house, and Jupiter/Saturn/Rahu passing over natal
     * grahas. `birth` is the natal chart (its lat/lon are sent as the birth place for the lagna
     * sections); date/time/tz are the transit moment.
     *
     * Cost: 20 credits per call.
     *
     * `GET /v1/vedic/narrative/transit-phal`
     *
     * @param array{date: string, time: string, tz: string, lat: float|int, lon: float|int} $birth
     *     Natal chart: birth `date`, `time`, `tz`, `lat`, `lon`, sent as `birth.*`; `lat` / `lon`
     *     also unprefixed.
     * @param string $date Date of the moment to check, e.g. the transit date (YYYY-MM-DD).
     * @param string $time Local time, 24-hour `HH:MM`.
     * @param string $tz Timezone: IANA name (Asia/Kolkata) or UTC offset (+05:30).
     * @param Ayanamsa|string|null $ayanamsa Sidereal ayanamsa (`Ayanamsa` case or value); the API
     *     uses Lahiri when left out.
     * @param Lang|string|null $lang Response language: a `Lang` case or its code (`'hi'`, `'gu'`,
     *     ...). Sent as `lang` and `locale`.
     * @param RequestOptions|null $requestOptions Per-call timeout, raw body or onResponse hook.
     *
     * @return array<mixed> The decoded JSON response.
     *
     * @throws LifeAstroException On an API error or a network failure.
     */
    public function transitPhal(
        array $birth,
        string $date,
        string $time,
        string $tz,
        Ayanamsa|string|null $ayanamsa = null,
        Lang|string|null $lang = null,
        ?RequestOptions $requestOptions = null,
    ): array {
        $query = [];
        Query::putFields($query, 'birth.', $birth);
        Query::putFields($query, '', $birth, ['lat', 'lon']);
        Query::put($query, 'date', $date);
        Query::put($query, 'time', $time);
        Query::put($query, 'tz', $tz);
        Query::put($query, 'ayanamsa', $ayanamsa);
        Query::put($query, 'lang', $lang);
        Query::put($query, 'locale', $lang);

        return $this->http->requestArray('/v1/vedic/narrative/transit-phal', $query, $requestOptions);
    }

